import sqlite3
import hashlib
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT UNIQUE
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, api_key) VALUES ('admin', ?, 'admin', 'ak_prod_7f3a9b2c')", (admin_hash,))
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    # Internal health checks bypass auth
    if request.path == '/healthz':
        return None
    key = request.headers.get('X-API-Key', '')
    if not key:
        return jsonify({'error': 'missing api key'}), 401

@app.route('/healthz')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent schema leakage
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid search field'}), 400

    # Build query with field validation (field is from allowed list)
    # Value is user-controlled - using LIKE for partial match
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v1/users/<username>/role', methods=['PUT'])
def update_role(username):
    """Update user role. Requires admin API key."""
    key = request.headers.get('X-API-Key', '')
    db = get_db()
    actor = db.execute("SELECT username, role FROM users WHERE api_key = ?", (key,)).fetchone()
    if not actor or actor['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    new_role = request.json.get('role', 'user')
    if new_role not in ['user', 'moderator', 'admin']:
        return jsonify({'error': 'invalid role'}), 400

    db.execute("UPDATE users SET role = ? WHERE username = ?", (new_role, username))
    db.execute("INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
              ('role_change', actor['username'], f"{username}->{new_role}"))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/api/v1/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries. Paginated."""
    page = request.args.get('page', '1')
    try:
        page_num = max(1, int(page))
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 50
    db = get_db()
    logs = db.execute("SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT 50 OFFSET ?", (offset,)).fetchall()
    return jsonify({'logs': [dict(row) for row in logs]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
